// Botao.tsx -- recebe props
interface BotaoProps {
  texto: string;
  variante: "primary" | "secondary" | "danger";
}

function Botao({ texto, variante }: BotaoProps) {
  return <button className={`botao botao--${variante}`}>{texto}</button>;
}

export default Botao;

// App.tsx -- envia props
function App() {
  return (
    <div>
      <Botao texto="Salvar" variante="primary" />
      <Botao texto="Cancelar" variante="secondary" />
      <Botao texto="Excluir" variante="danger" />
    </div>
  );
}

// Card.tsx
interface CardProps {
  titulo: string;
  children: React.ReactNode;
  footer?: React.ReactNode;
}

function Card({ titulo, children, footer }: CardProps) {
  return (
    <div className="card">
      <div className="card__header">
        <h2>{titulo}</h2>
      </div>
      <div className="card__body">
        {children}
      </div>
      {footer && (
        <div className="card__footer">{footer}</div>
      )}
    </div>
  );
}

// Usando com children
function App() {
  return (
    <Card
      titulo="Programacao Web II"
      footer={<button>Ver mais</button>}
    >
      <p>Aprenda Next.js, React e Prisma do zero ao deploy.</p>
      <ul>
        <li>7 modulos</li>
        <li>Projeto final fullstack</li>
      </ul>
    </Card>
  );
}

