// 3. Variavel calculada antes do return -- para logica mais complexa
function StatusAluno({ media }: { media: number }) {
  let texto = "Reprovado";
  let cor = "vermelho";

  if (media >= 7) {
    texto = "Aprovado";
    cor = "verde";
  } else if (media >= 5) {
    texto = "Recuperacao";
    cor = "amarelo";
  }

  return <span className={`badge badge--${cor}`}>{texto}</span>;
}

interface Projeto {
  id: number;
  titulo: string;
  tecnologia: string;
}

const projetos: Projeto[] = [
  { id: 1, titulo: "Portfolio Pessoal", tecnologia: "React" },
  { id: 2, titulo: "API de Tarefas", tecnologia: "Node.js" },
  { id: 3, titulo: "Dashboard", tecnologia: "React" },
];

function ListaProjetos() {
  return (
    <ul>
      {projetos.map((projeto) => (
        <li key={projeto.id}>
          {projeto.titulo} -- {projeto.tecnologia}
        </li>
      ))}
    </ul>
  );
}
